from gurobipy import Model, GRB, quicksum

def build_and_solve():
    cabinets = []
    capacities = {}
    products = []
    values = {}
    weights = {}
    for rec in LEGACY_RECORDS:
        src = rec['source']
        vals = rec['values']
        if src.endswith('capacity.csv'):
            cab_id = vals['CabinetID']
            cabinets.append(cab_id)
            capacities[cab_id] = float(vals['Capacity'])
        elif src.endswith('products.csv'):
            pname = vals['ProductName']
            products.append(pname)
            values[pname] = float(vals['Value'])
            weights[pname] = float(vals['Weight'])
    if len(cabinets) == 0 or len(products) == 0:
        raise ValueError('Missing cabinets or products data.')
    for cab in cabinets:
        if cab not in capacities:
            raise ValueError(f'Missing capacity for cabinet {cab}')
    for prod in products:
        if prod not in values or prod not in weights:
            raise ValueError(f'Missing value or weight for product {prod}')
    m = Model()
    m.Params.MIPGap = 0.0001
    x_vars = {}
    for cab in cabinets:
        x_vars[cab] = {}
        for prod in products:
            x_vars[cab][prod] = m.addVar(vtype=GRB.INTEGER, lb=0, name='x')
    m.setObjective(quicksum((values[prod] * x_vars[cab][prod] for cab in cabinets for prod in products)), GRB.MAXIMIZE)
    for cab in cabinets:
        m.addConstr(quicksum((weights[prod] * x_vars[cab][prod] for prod in products)) <= capacities[cab], name='cap')
    m.update()
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print('ObjVal', m.ObjVal)
        for cab in cabinets:
            for prod in products:
                var = x_vars[cab][prod]
                print(var.VarName, var.X)
    else:
        print('Status', m.Status)
    return m
m = build_and_solve()